if(PHP_SAPI!=='cli'||getenv('PHPBB_KB_COUNTER_NATIVE')!=='1'){echo "KB seed checks require explicit disposable storage.\n";return;}
function kps_state(){
 $out=kp_snapshot();foreach($out as&$rows){usort($rows,function($a,$b){return strcmp(json_encode($a),json_encode($b));});}unset($rows);
 $out['_identity']=kp_rows("SELECT TABLE_NAME,AUTO_INCREMENT FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME");return$out;
}
class KpsCommitProxy{
 var$inner;var$mode;var$target;var$fired=false;function __construct($inner,$mode,$target='COMMIT'){$this->inner=$inner;$this->mode=$mode;$this->target=$target;}function __call($m,$a){return call_user_func_array(array($this->inner,$m),$a);}
 function sql_query($sql,$transaction=false){if($sql===$this->target&&!$this->fired){$this->fired=true;if($this->mode==='after'){$this->inner->sql_query($sql,$transaction);}return false;}return$this->inner->sql_query($sql,$transaction);}
}
function kps_denied($callback){$denied=false;try{call_user_func($callback);}catch(RuntimeException$error){$denied=true;}kp_check($denied,'Invalid/failing fixture seed must be refused');}
function kps_suite(){
 $cases=0;$source=file_get_contents(__DIR__.'/check-kb-publication-native.php');kp_check(preg_match('/^function kp_seed_rows\(.*?^\}/ms',$source,$m)===1,'Preserved original seed body');
 $original=str_replace('function kp_seed_rows(','function kp_reset(',str_replace("\r\n","\n",$m[0]));kp_check(hash('sha256',$original)==='283f0cdeb08ad7802d736b963fe2b21c1bda78719e768d9cb6c895b87148e132','Original complete seed bytes unchanged');
 foreach(array('root','junior','moderator','ordinary')as$actor){foreach(array(false,true)as$comments){kp_seed_rows($actor,$comments);$old=kps_state();$user=$GLOBALS['userdata'];$post=$_POST;$method=$_SERVER['REQUEST_METHOD'];kp_reset($actor,$comments);kp_check(kps_state()===$old&&$GLOBALS['userdata']===$user&&$_POST===$post&&$_SERVER['REQUEST_METHOD']===$method,'Exact original rows/identities and request state '.$actor);$cases++;}}
 kp_reset();$before=kps_state();kps_denied(function(){kp_seed_batch(function(){kp_sql("UPDATE fixture_kb_articles SET article_title='rollback'");throw new RuntimeException('Synthetic setup callback failure');});});kp_check(kps_state()===$before,'Late callback failure rolls back all rows');$cases++;
 kp_sql("CREATE TRIGGER kps_late BEFORE INSERT ON fixture_forums FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic setup failure'");$user=$GLOBALS['userdata'];$post=$_POST;$server=$_SERVER;
 try{kps_denied(function(){kp_reset('ordinary',true);});kp_check(kps_state()===$before&&$GLOBALS['userdata']===$user&&$_POST===$post&&$_SERVER===$server,'Real late seed SQL failure preserves database and PHP request state');$cases++;}finally{kp_sql('DROP TRIGGER kps_late');}
 foreach(array('before','after')as$mode){kp_reset();kp_sql("UPDATE fixture_kb_articles SET article_title='Previous seed'");$before=kps_state();$peer=$GLOBALS['peer'];$proxy=new KpsCommitProxy($peer,$mode);$GLOBALS['peer']=$proxy;try{kps_denied(function(){kp_reset();});kp_check($proxy->fired,'Exact own commit fault reached');}finally{$GLOBALS['peer']=$peer;}
  if($mode==='before'){kp_check(kps_state()===$before,'Uncommitted seed fully rolls back');}else{kp_check(kp_rows('SELECT article_title FROM fixture_kb_articles')===array(array('article_title'=>'Synthetic title')),'Lost seed ACK retains a complete actual commit, never retries');}$cases++;
 }
 foreach(array('before','after')as$mode){kp_reset();$before=kps_state();$peer=$GLOBALS['peer'];$proxy=new KpsCommitProxy($peer,$mode,'START TRANSACTION');$GLOBALS['peer']=$proxy;try{kps_denied(function(){kp_reset();});kp_check($proxy->fired,'Exact own begin fault reached');}finally{$GLOBALS['peer']=$peer;}kp_check(kps_state()===$before&&$peer->sql_query('SET TRANSACTION READ WRITE')!==false,'Unconfirmed begin leaves rows unchanged and no owned transaction open');$cases++;}
 kp_reset();$before=kps_state();kp_sql('START TRANSACTION');kp_sql("UPDATE fixture_kb_articles SET article_title='Pending peer'");try{kps_denied(function(){kp_reset('ordinary');});kp_check(kp_rows('SELECT article_title FROM fixture_kb_articles')===array(array('article_title'=>'Pending peer')),'Outer pending work remains owned');}finally{kp_sql('ROLLBACK');}kp_check(kps_state()===$before,'Rejected seed cannot commit outer peer transaction');$cases++;
 kp_sql('SET autocommit=0');kp_sql("UPDATE fixture_kb_articles SET article_title='Manual peer'");try{kps_denied(function(){kp_reset();});kp_check(kp_rows('SELECT article_title FROM fixture_kb_articles')===array(array('article_title'=>'Manual peer')),'Manual autocommit work remains pending');}finally{kp_sql('ROLLBACK');kp_sql('SET autocommit=1');}kp_check(kps_state()===$before,'Manual transaction preserved without implicit commit');$cases++;
 kp_sql('USE information_schema');try{kps_denied(function(){kp_reset();});$cases++;}finally{kp_sql('USE '.$GLOBALS['fixture']);}kp_check(kps_state()===$before,'Foreign schema never seeded');
 kp_sql('ALTER TABLE fixture_words ENGINE=MyISAM');try{kps_denied(function(){kp_reset();});kp_check(kps_state()===$before,'Nontransactional participant refuses before row writes');$cases++;}finally{kp_sql('ALTER TABLE fixture_words ENGINE=InnoDB ROW_FORMAT=DYNAMIC');}
 foreach(array('COMMIT','ROLLBACK','ALTER TABLE fixture_users ADD unexpected INT')as$sql){$before=kps_state();kps_denied(function()use($sql){kp_seed_batch(function()use($sql){kp_sql("UPDATE fixture_kb_articles SET article_title='Cannot escape'");kp_sql($sql);});});kp_check(kps_state()===$before,'Seed row callback cannot escape ownership '.$sql);$cases++;}
 kps_denied(function(){kp_seed_batch(function(){kp_sql("UPDATE fixture_kb_articles SET article_title='Nested'");kp_seed_batch(function(){});});});kp_check(kps_state()===$before,'Nested seed refuses without committing its parent');$cases++;
 $db=$GLOBALS['db'];$r=$db->sql_query('SELECT @@SESSION.lock_wait_timeout seconds');$wait=$db->sql_fetchrow($r);$db->sql_freeresult($r);kp_check($db->sql_query('SET SESSION lock_wait_timeout=0')!==false,'Scoped independent DDL wait');
 try{kp_seed_batch(function()use($db){$r=$db->sql_query('ALTER TABLE fixture_words ENGINE=MyISAM');$error=$db->sql_error();kp_check($r===false&&(int)$error['code']===1205,'Grouped LIMIT0 pins even empty trailing participants against real independent DDL');});$cases++;}finally{kp_check($db->sql_query('SET SESSION lock_wait_timeout='.(int)$wait['seconds'])!==false,'Original independent DDL wait restored');}
 kp_sql('RENAME TABLE fixture_words TO fixture_kps_missing');try{kps_denied(function(){kp_reset();});$cases++;}finally{kp_sql('RENAME TABLE fixture_kps_missing TO fixture_words');}kp_check(kps_state()===$before,'Missing participant leaves every surviving table untouched');
 echo 'KB fixture seed batches: '.$cases." checks PASS; original eight row/identity/request states, actual late SQL and callback failures, commit ACK loss, outer/manual transactions, foreign schemas, legacy/missing tables and transaction escapes.\n";
}
$source=file_get_contents(__DIR__.'/check-kb-publication-native.php');$anchor=' $cases = 0;';if(substr_count($source,$anchor)!==1){throw new RuntimeException('Original publication dispatch boundary');}$source=str_replace($anchor,' kps_suite();return;'.$anchor,$source);
$code='';foreach(token_get_all($source)as$t){$code.=is_array($t)?($t[0]===T_DIR?var_export(__DIR__,true):$t[1]):$t;}eval(substr($code,5));
